"""Build a standalone AC evidence viewer with exact raw answers and vote books.

The original panorama is embedded unchanged. SVG overlays are computed from
saved corner coordinates; no image generation, fusion, scoring or ring repair
occurs. Every source answer and every selected/unselected native group remains
available for inspection and download.
"""
import argparse,base64,gzip,hashlib,io,json
from pathlib import Path

HTML=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HOHONET v2.1 直接AC证据查看器</title>
<style>
__FONT_FACE__
:root{--ink:#203043;--muted:#586779;--paper:#f3f5f8;--a:#2471a3;--c:#d95f28;--line:#d6dee8}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 system-ui,"Noto Sans CJK SC",sans-serif}header{padding:24px 4vw;background:#142b43;color:white}h1{font-size:25px;margin:0 0 8px}header p{max-width:1000px;margin:0;color:#d9e6f4}.wrap{margin:22px 3vw 60px}.box{background:white;border:1px solid var(--line);border-radius:12px;padding:18px;margin:18px 0}.toolbar{display:flex;gap:16px;align-items:center;flex-wrap:wrap}select,button{font:inherit;padding:7px 11px;border:1px solid #b9c7d8;border-radius:6px;background:white;color:var(--ink)}button{cursor:pointer}button:hover{background:#eaf2fa}select{max-width:100%}h2{font-size:20px;margin:0 0 12px}h3{font-size:17px;margin:0 0 8px}.meta{color:var(--muted);white-space:pre-wrap}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.pane{min-width:0}.pane.a h3{color:var(--a)}.pane.c h3{color:var(--c)}svg.pano{width:100%;height:auto;background:#111;border-radius:7px;border:1px solid var(--line)}.workers{display:flex;gap:5px;flex-wrap:wrap;margin-top:10px}.worker{padding:3px 7px;border:1px solid #dce3eb;border-radius:5px;font-size:12px;background:#f9fbfd}.worker.d{background:#edf0f3}.worker.x{border-color:#2471a3}.worker.z{border-color:#d95f28}.scroll{overflow:auto;max-height:540px}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:7px 9px;text-align:left;border-bottom:1px solid #e2e8ee;vertical-align:top}.table th{position:sticky;top:0;background:#edf2f8}.table tr:hover td{background:#f2f7fb}.table tr.unselected td{color:#7d8793;background:#f7f8fa}code{font-size:12px;word-break:break-all}.tag{display:inline-block;border-radius:20px;padding:2px 10px;background:#edf2f8;margin-right:6px;font-size:12px}.bad{color:#9d2534}.note{color:#586779;font-size:13px}.download{display:flex;gap:9px;flex-wrap:wrap}details{margin:12px 0;border:1px solid #dce3eb;border-radius:7px;padding:9px 12px}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;word-break:break-all;font-size:12px;max-height:420px;overflow:auto;background:#f4f6f8;padding:10px}.votehead{display:flex;gap:8px;justify-content:space-between}.empty{padding:15px;background:#fff2f2}.focus{outline:3px solid #e5b650}@media(max-width:950px){.two{grid-template-columns:1fr}.wrap{margin:15px 12px}header{padding:20px}h1{font-size:22px}}
</style></head><body><header><h1>HOHONET v2.1：不同人群如何改变同一张图的共识</h1><p>直接 A/C、整类替换与类别联盟的精确证据。可以逐人打开完整原答，查看同一目标参考、两队输出、所有候选对应组与连接记录。缺失质量分数保留为空。</p></header><main class="wrap">
<section class="box"><div class="toolbar"><label>案例 <select id="case"></select></label><span id="casecount" class="tag"></span></div><h2 id="title" style="margin-top:15px"></h2><p id="purpose"></p><div id="meta" class="meta"></div><div id="downloads" class="download" style="margin-top:12px"></div></section>
<section class="box"><h2>原图、完整原答与融合候选</h2><div class="toolbar"><label><input type="checkbox" id="showref" checked> 当前目标参考（黑色虚线）</label><label><input type="checkbox" id="showoutput" checked> 两队候选输出</label><label><input type="checkbox" id="showgroups"> 所有对应组位置（含未入选）</label><button id="allraw">显示全部原答</button><button id="noraw">隐藏全部原答</button><button id="donly">只显示共同背景D</button><button id="blockonly">只显示替换块X/Z</button></div><p class="note">原答使用完整角点与原始顺序；ERP边界按保存角点间的大圆弧绘制。没有连接结果时，只显示实际存在的节点，不补横向边。原图为2048×1024，坐标视图为1024×512。</p><div class="two"><div class="pane a"><h3 id="a_title"></h3><svg id="a_svg" class="pano" viewBox="0 0 1024 512"></svg><div id="a_workers" class="workers"></div></div><div class="pane c"><h3 id="c_title"></h3><svg id="c_svg" class="pano" viewBox="0 0 1024 512"></svg><div id="c_workers" class="workers"></div></div></div></section>
<section class="box"><h2>质量、结构、位置、尺度与记录劳动</h2><div class="scroll"><table class="table"><thead><tr><th>指标</th><th>A</th><th>C</th><th>C−A</th></tr></thead><tbody id="metrics"></tbody></table></div><p id="time_note" class="note"></p><p class="note">底面间距 1−IoU 无量纲；底面质心距离和坐标单位为相机高度 h，面积为 h²。这些是归一化几何，不能直接当作房间实测米数。直接AC没有同类B对照，不能单凭此页声称跨类变化大于同类。</p></section>
<section class="box"><h2>全部候选对应组与支持者</h2><p class="note">票门槛是全团队 ceil(N/2)，偶数团队正好一半可以入选。人数足够只是支持能力；同一组是否过票、位置能否确定、选中组能否连接需要分别检查。浅色行是未入选组。</p><div class="two"><div><h3>A票账</h3><div class="scroll" id="a_votes"></div></div><div><h3>C票账</h3><div class="scroll" id="c_votes"></div></div></div></section>
<section class="box"><h2>来源顺序与连接记录</h2><p class="note">本页保留完整source assignment、直接边/投影边支持与备选环。局部 g编号只在该队内部有意义，跨队应通过原答object_id和source_pair_index追踪。没有共同观察者本身不能证明两种结构在物理上互斥。</p><div class="two"><div id="a_connection"></div><div id="c_connection"></div></div></section>
<section class="box"><h2>完整原答、楼外冻结标签与复现数据</h2><div id="rawdetails"></div><details><summary>当前事件与来源合同</summary><pre id="provenance"></pre></details></section></main>
<script>const DATA=__DATA__;
const NS='http://www.w3.org/2000/svg',color={A:'#2471a3',C:'#d95f28'};let chosen=DATA.cases[0],visible=new Set();
const truth=x=>x===true||x==='True'||x==='true';
const $=id=>document.getElementById(id),list=s=>s?s.split('|'):[],num=x=>x===null||x===undefined||x===''?'不可评':typeof x==='number'?(Number.isInteger(x)?String(x):x.toFixed(5)):String(x);
function node(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n}
function svg(tag,attrs){const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attrs||{}))n.setAttribute(k,v);return n}
function ray(p){let u=p[0]*2*Math.PI/1024,v=(.5-p[1]/512)*Math.PI;return[-Math.sin(u)*Math.cos(v),Math.cos(u)*Math.cos(v),Math.sin(v)]}
function arcs(p,q,n=50){const a=ray(p),b=ray(q),dot=Math.max(-1,Math.min(1,a.reduce((s,x,i)=>s+x*b[i],0))),angle=Math.acos(dot),sine=Math.sin(angle),segments=[[]];let prior;
for(let i=0;i<n;i++){let t=i/(n-1),r=a.map((x,j)=>Math.abs(sine)<1e-8?(1-t)*x+t*b[j]:Math.sin((1-t)*angle)/sine*x+Math.sin(t*angle)/sine*b[j]),length=Math.hypot(...r);r=r.map(x=>x/length);const x=((Math.atan2(-r[0],r[1])%(2*Math.PI))+2*Math.PI)%(2*Math.PI)*1024/(2*Math.PI),y=(.5-Math.asin(Math.max(-1,Math.min(1,r[2])))/Math.PI)*512;if(prior!==undefined&&Math.abs(x-prior)>512)segments.push([]);segments.at(-1).push([x,y]);prior=x}return segments.filter(x=>x.length>1)}
function outline(parent,points,c,width,opacity,dash){if(!points||points.length%2||points.length<2)return;let segments=[];for(let side=0;side<2;side++){const ring=points.filter((_,i)=>i%2===side);for(let i=0;i<ring.length;i++)segments.push(...arcs(ring[i],ring[(i+1)%ring.length]))}for(let i=0;i<points.length;i+=2)segments.push(...arcs(points[i],points[i+1],15));const path=segments.map(seg=>'M'+seg.map(p=>p.map(x=>x.toFixed(3)).join(',')).join('L')).join('');if(width>=1.6)parent.append(svg('path',{d:path,fill:'none',stroke:'white','stroke-width':width+1.1,opacity:.75}));parent.append(svg('path',{d:path,fill:'none',stroke:c,'stroke-width':width,opacity,'stroke-dasharray':dash||''}))}
function groups(parent,row,c){for(const g of(row.full_state?.identity_groups||[])){if(!g.center)continue;const p=g.center,opacity=g.selected?.95:.4;parent.append(svg('line',{x1:p[0][0],y1:p[0][1],x2:p[1][0],y2:p[1][1],stroke:c,'stroke-width':1.3,opacity}));for(const point of p)parent.append(svg('circle',{cx:point[0],cy:point[1],r:g.selected?3:2,fill:g.selected?c:'white',stroke:c,'stroke-width':1,opacity}));const label=svg('text',{x:p[1][0]+3,y:p[1][1]+10,fill:c,stroke:'white','stroke-width':2,'paint-order':'stroke','font-size':10});label.textContent=g.feature_id.replace('node_','g')+' '+g.support;parent.append(label)}}
function draw(){const raw=Object.fromEntries(chosen.pool.records.map(r=>[r.worker_id,r]));for(const arm of['A','C']){const panel=$(arm.toLowerCase()+'_svg');panel.replaceChildren();panel.append(svg('image',{href:DATA.images[chosen.event.image],x:0,y:0,width:1024,height:512}));for(const w of chosen.arms[arm].member_workers)if(visible.has(w)){const d=list(chosen.event.D_workers).includes(w);outline(panel,raw[w].points,d?'#8a99aa':color[arm],.85,.65)}if($('showref').checked){outline(panel,chosen.reference.points_1024x512,'#111',1.7,1,'5 3');chosen.reference.points_1024x512.filter((_,i)=>i%2===1).forEach((p,i)=>{const t=svg('text',{x:p[0]+3,y:p[1]+12+(i%2)*8,fill:'#111',stroke:'white','stroke-width':2,'paint-order':'stroke','font-size':9});t.textContent='r'+(i+1);panel.append(t)})}if($('showoutput').checked)outline(panel,chosen.arms[arm].geometry?.points,color[arm],2.1,1);if($('showgroups').checked||!chosen.arms[arm].geometry?.points)groups(panel,chosen.arms[arm],color[arm])}}
function table(headers,rows){const t=node('table');t.className='table';const h=node('thead'),hr=node('tr');headers.forEach(x=>hr.append(node('th',x)));h.append(hr);t.append(h);const body=node('tbody');for(const r of rows){const tr=node('tr');if(r.unselected)tr.className='unselected';r.cells.forEach(x=>tr.append(node('td',x)));body.append(tr)}t.append(body);return t}
function download(name,data,mime='application/json'){const a=node('a'),blob=new Blob([data],{type:mime}),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function button(label,fn){const b=node('button',label);b.onclick=fn;return b}
function renderVotes(arm){const row=chosen.arms[arm],d=new Set(list(chosen.event.D_workers)),box=$(arm.toLowerCase()+'_votes');const rows=(row.full_state?.identity_groups||[]).map(g=>{const workers=g.members.map(m=>m.worker||chosen.pool.records.find(r=>r.object_id===m.id)?.worker_id),nd=workers.filter(w=>d.has(w)).length;return{unselected:!g.selected,cells:[g.feature_id.replace('node_','g'),g.selected?'入选':'未选',g.support+' / '+row.minimum_support,nd+' + '+(workers.length-nd),g.center?'已定位':'未定位',workers.join('、')]}});box.replaceChildren(table(['组','状态','支持/门槛','D+替换','定位','全部支持者'],rows))}
function renderConnection(arm){const row=chosen.arms[arm],state=row.full_state||{},selected=new Set((state.identity_groups||[]).filter(g=>g.selected).map(g=>g.feature_id)),container=$(arm.toLowerCase()+'_connection');container.replaceChildren(node('h3',arm+'：'+row.score_status));const covering=(state.assignments||[]).filter(r=>{const projection=r.feature_ids.filter(x=>selected.has(x));return selected.size>=3&&projection.length===selected.size&&new Set(projection).size===selected.size});container.append(node('p','入选节点 '+selected.size+'；覆盖所有入选节点的来源环 '+covering.length+'：'+covering.map(x=>x.worker).join('、')));
for(const [label,data]of[['全部来源顺序',state.assignments],['直接边/投影边支持',state.ring_diagnostics?.edges],['备选环与完整连接诊断',state.ring_diagnostics]]){const d=node('details');d.append(node('summary',label),node('pre',JSON.stringify(data??null,null,2)));container.append(d)}}
function renderRaw(){const D=new Set(list(chosen.event.D_workers)),X=new Set(list(chosen.event.X_workers)),Z=new Set(list(chosen.event.Z_workers));const raw=chosen.pool.records.filter(r=>D.has(r.worker_id)||X.has(r.worker_id)||Z.has(r.worker_id));const box=$('rawdetails');box.replaceChildren();for(const r of raw){const block=D.has(r.worker_id)?'D':X.has(r.worker_id)?'X':'Z',label=chosen.frozen_lobo_labels?.[r.worker_id]||{};const d=node('details');d.append(node('summary',block+' · '+r.worker_id+' · 冻结类 '+(truth(label.known)?label.class_id:'未知')+' · '+r.points.length/2+'个原答角点对'));d.append(button('仅看此人',()=>{visible=new Set([r.worker_id]);syncWorkerChecks();draw()}));d.append(node('pre',JSON.stringify({original_full_answer:r,frozen_outside_building_label:label},null,2)));box.append(d)}}
function syncWorkerChecks(){document.querySelectorAll('[data-worker]').forEach(el=>{el.checked=visible.has(el.dataset.worker)})}
function allianceLabels(){const s=chosen.selection;if(!s.A_alliance||!s.C_alliance)return null;return Number(s.input_orientation_sign)===1?{A:s.A_alliance,C:s.C_alliance}:{A:s.C_alliance,C:s.A_alliance}}
function render(){const e=chosen.event;visible=new Set();$('title').textContent=e.image+' · '+e.method;$('purpose').textContent=chosen.selection.purpose_zh||chosen.selection.purpose||chosen.selection.reason||'';$('casecount').textContent=DATA.cases.length+' 个精确事件';$('meta').textContent=`${e.condition} / ${e.layer} / ${e.scope}\n人数 ${e.n_A} → ${e.n_C}；换出 X=${e.m_X}，换入 Z=${e.m_Z}；D=${list(e.D_workers).length}。 ${truth(e.equal_team_size)?'等人数比较。':'人数与构成同时变化。'}\n类别构成 A=${e.A_class_counts||e.source_class}；C=${e.C_class_counts||e.target_class}\n本页规范方向 C−A；参考 ${e.reference_id}\nA：${chosen.arms.A.score_status}；C：${chosen.arms.C.score_status}`;
const unions=allianceLabels();if(unions)$('meta').textContent+='\n联盟：本页 A='+unions.A.replaceAll('|','+')+'；C='+unions.C.replaceAll('|','+')+'。原登记比较 '+chosen.selection.A_alliance.replaceAll('|','+')+' → '+chosen.selection.C_alliance.replaceAll('|','+')+'（原方向符号 '+chosen.selection.input_orientation_sign+'）。';
$('downloads').replaceChildren(button('下载完整案例JSON',()=>download(e.event_id+'.json',JSON.stringify(chosen,null,2))),button('下载全部原答JSON',()=>download(e.image+'_full_original_answers.json',JSON.stringify(chosen.pool.records,null,2))),button('下载全原图',()=>{const a=node('a');a.href=DATA.images[e.image];a.download=e.image+'.png';a.click()}));
const labels={B8L2:'B8L2',D10:'D10',IoU3D100:'3D IoU×100',iou_2d:'底面IoU',boundary_loss:'边界损失',direction_loss:'方向损失',height_loss:'高度损失',nodes:'入选节点',fusion_turn_n:'有效转折',fusion_short_turn_edges:'短结构边',ref_node_recall_9:'参考节点保留（9°）',ref_edge_recall_9:'参考边保留（9°）',geometry_area_h2:'底面面积 h²',centroid_x_h:'质心x/h',centroid_z_h:'质心z/h',height_mean_h:'平均高度/h',source_time_total_seconds:'全部已知记录劳动秒数',minimum_support:'MV50门槛'};$('metrics').replaceChildren();for(const [key,label]of Object.entries(labels)){const a=chosen.arms.A[key],c=chosen.arms.C[key],delta=key==='source_time_total_seconds'?chosen.metrics.record_time_CA_seconds_source_matched:typeof a==='number'&&typeof c==='number'?c-a:null;const tr=node('tr');[label,num(a),num(c),num(delta)].forEach(x=>tr.append(node('td',x)));$('metrics').append(tr)}
const m=chosen.metrics;$('time_note').textContent=`记录来源计数向量完全匹配：${truth(m.time_comparable_source_count_AC)?'是':'否'}；全部已知且同一单一记录来源：${truth(m.time_comparable_single_source_AC)?'是':'否'}。严格同源计数控制下劳动变化：${num(m.record_time_CA_pct_source_matched)}%；同单一来源的每成员变化：${num(m.record_time_per_member_CA_pct_single_source)}%。历史记录劳动不等于融合CPU时间，也不是新开展的同步标注速度实验。`;
for(const arm of['A','C']){const row=chosen.arms[arm],container=$(arm.toLowerCase()+'_workers');$(arm.toLowerCase()+'_title').textContent=arm+(unions?' ('+unions[arm].replaceAll('|','+')+')':'')+'：'+row.k+'人，B8L2 '+num(row.B8L2)+'，'+row.score_status;container.replaceChildren();for(const worker of row.member_workers){const D=list(e.D_workers).includes(worker),block=D?'D':arm==='A'?'X':'Z',label=node('label');label.className='worker '+block.toLowerCase();const input=node('input');input.type='checkbox';input.dataset.worker=worker;input.onchange=()=>{if(input.checked)visible.add(worker);else visible.delete(worker);syncWorkerChecks();draw()};label.append(input,document.createTextNode(block+' '+worker));container.append(label)}renderVotes(arm);renderConnection(arm)}renderRaw();$('provenance').textContent=JSON.stringify({event:e,selection:chosen.selection,reference_metadata:chosen.pool.meta,interpretation_limits:chosen.interpretation_limits},null,2);draw()}
DATA.cases.forEach((c,i)=>{const o=node('option',c.event.image+' · '+c.event.method+' · '+(c.selection.A_alliance?c.selection.A_alliance.replaceAll('|','+')+' → '+c.selection.C_alliance.replaceAll('|','+')+' · ':'')+'n '+c.event.n_A+'→'+c.event.n_C+' / m '+c.event.m_X+'→'+c.event.m_Z+' · '+(c.selection.purpose_zh||c.selection.purpose||c.event.event_id));o.value=i;$('case').append(o)});$('case').onchange=()=>{chosen=DATA.cases[Number($('case').value)];render()};for(const id of['showref','showoutput','showgroups'])$(id).onchange=draw;
$('allraw').onclick=()=>{visible=new Set([...chosen.arms.A.member_workers,...chosen.arms.C.member_workers]);syncWorkerChecks();draw()};$('noraw').onclick=()=>{visible.clear();syncWorkerChecks();draw()};$('donly').onclick=()=>{visible=new Set(list(chosen.event.D_workers));syncWorkerChecks();draw()};$('blockonly').onclick=()=>{visible=new Set([...list(chosen.event.X_workers),...list(chosen.event.Z_workers)]);syncWorkerChecks();draw()};render();
</script></body></html>'''

def main():
    ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--cases',nargs='+',required=True);ap.add_argument('--originals',required=True);ap.add_argument('--out',required=True);a=ap.parse_args()
    cases=[];images={};manifest=[]
    for path in a.cases:
        path=Path(path)
        with gzip.open(path,'rt') as f:case=json.load(f)
        image=case['event']['image'];cases.append(case)
        if image not in images:
            p=Path(a.originals)/(image+'.png');content=p.read_bytes();images[image]='data:image/png;base64,'+base64.b64encode(content).decode()
            manifest.append({'image':image,'path':str(p),'sha256':hashlib.sha256(content).hexdigest(),'bytes':len(content)})
    data=json.dumps({'cases':cases,'images':images},ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('<','\\u003c').replace('>','\\u003e')
    # An embedded subset gives a reproducible Chinese rendering even on a
    # computer with no installed CJK fonts; the original OFL font is unchanged.
    from fontTools import subset
    from fontTools.ttLib import TTFont
    font_path=Path(__file__).resolve().parents[1]/'source/NotoSansCJKsc-Regular.otf'
    font=TTFont(font_path);subsetter=subset.Subsetter()
    subsetter.populate(text=HTML+json.dumps(cases,ensure_ascii=False));subsetter.subset(font)
    font_buffer=io.BytesIO();font.save(font_buffer);font_bytes=font_buffer.getvalue();font.close()
    font_css="@font-face{font-family:HohonetEvidence;src:url(data:font/otf;base64,"+base64.b64encode(font_bytes).decode()+") format('opentype');font-weight:100 900;font-style:normal;font-display:block}"
    html=HTML.replace('__DATA__',data).replace('__FONT_FACE__',font_css).replace('system-ui,"Noto Sans CJK SC",sans-serif','HohonetEvidence,system-ui,"Noto Sans CJK SC",sans-serif')
    out=Path(a.out);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(html,encoding='utf-8')
    receipt={'case_events':len(cases),'unique_images':len(images),'unique_endpoint_keys':len({r['team_key'] for c in cases for r in c['arms'].values()}),'html_bytes':out.stat().st_size,
             'all_original_answers_embedded':True,'all_native_vote_and_connection_states_embedded':True,'external_network_requests':0,'new_fusions':0,'new_scores':0,
             'source_images':manifest,'viewer_sha256':hashlib.sha256(out.read_bytes()).hexdigest(),
             'embedded_subset_font':{'source':str(font_path),'source_sha256':hashlib.sha256(font_path.read_bytes()).hexdigest(),
                                     'subset_bytes':len(font_bytes),'subset_sha256':hashlib.sha256(font_bytes).hexdigest()}}
    out.with_suffix('.receipt.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in receipt.items() if k!='source_images'}),flush=True)

if __name__=='__main__':main()
